const text = $input.first().json.text;
try {
  const parsed = JSON.parse(text);
  return [{ json: parsed }];
} catch (e) {
  // Si falla el parsing estricto, devolvemos el texto para que el parser del backend lo procese de forma robusta
  return [{ json: { raw_response: text, error: e.message } }];
}

